var hm = GameState.state.units["U_HELLBLASTER_SQUAD_A"].models
for i in range(hm.size()):
	hm[i]["current_wounds"] = 1 if i == 0 else 12
	if i > 0:
		hm[i]["wounds"] = 12
return H.setup(2, {"cp": {"1": 0}})

